// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint64 callValue, uint64 seedBalance) public {
        vm.assume(callValue == 10 ether);
        vm.assume(blockNum > 0);

        vm.roll(blockNum);
        vm.deal(address(c), seedBalance);

        vm.warp(1);

        address sender = address(0x1000);
        vm.deal(sender, callValue);

        vm.prank(sender);
        (bool ok,) = address(c).call{value: callValue}("");
        require(ok, "call failed");

        if (blockNum % 15 == 0) {
            assertEq(address(c).balance, 0);
        }
    }
}
